#!/usr/bin/env python3
import base64, hashlib, json, os, shutil, sys, time
from pathlib import Path
ROOT = Path('/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2')
TARGET = ROOT / 'plugin.py'
STATE = ROOT / 'embyflow_buffer_install_v3.json'
HELPER = ROOT / 'embyflow_buffer_v1.py'
OLD_HASH = '143003688c01d7a1e80963dbc25fca7ae1100a7f14091a11dad670bfdf841886'
NEW_HASH = '4aa660b030b1f540d5fa8f7d031e1d46a211d5153d84b5e5a0b61668da2b5f9e'
BASE_HASH = '9f6cf0333a182d4be428d35f24f0d2d363c3339866c1c796f39be5ab3dbce835'
HELPER_HASH = '43f7dd70171cb977d28363ead2ee8ba416f36ed25099c4cc162b5f6c58fa2240'
BRIDGE = base64.b64decode('')
OLD_BRIDGE = base64.b64decode('')

def digest(data): return hashlib.sha256(data).hexdigest()
def atomic(path,data,mode=0o644):
    tmp=Path(str(path)+'.v4-tmp')
    with tmp.open('wb') as h:
        h.write(data);h.flush();os.fsync(h.fileno())
    os.chmod(str(tmp),mode);os.replace(str(tmp),str(path))

def main():
    current=TARGET.read_bytes()
    state=json.loads(STATE.read_text())
    if '--restore' in sys.argv:
        if digest(current)!=NEW_HASH:raise RuntimeError('PY seit V4 verändert. Rückweg sicher abgebrochen.')
        original=Path(state['backup']).read_bytes()
        if digest(original)!=BASE_HASH:raise RuntimeError('Originalsicherung stimmt nicht.')
        atomic(TARGET,original,state['mode'])
        if HELPER.exists() and digest(HELPER.read_bytes())==HELPER_HASH:HELPER.unlink()
        STATE.unlink()
        print('Original vor dem Puffertest wiederhergestellt.')
        return
    if digest(current)!=OLD_HASH or state['installed']!=OLD_HASH:
        raise RuntimeError('Andere Pluginversion: erwartet wird der installierte Scrollpuffer V3. Nichts geändert.')
    if digest(HELPER.read_bytes())!=HELPER_HASH:raise RuntimeError('Puffer-Hilfsdatei verändert. Abbruch.')
    if not current.endswith(OLD_BRIDGE):raise RuntimeError('Einbaustelle abweichend.')
    updated=current[:-len(OLD_BRIDGE)]+BRIDGE
    if digest(updated)!=NEW_HASH:raise RuntimeError('Interne Prüfsumme abweichend.')
    compile(updated,'plugin.py','exec')
    backup=ROOT/('plugin_vor_PufferstatusV4_'+time.strftime('%Y%m%d_%H%M%S')+'.py')
    shutil.copy2(str(TARGET),str(backup))
    oldstate=STATE.read_bytes()
    state['installed']=NEW_HASH
    state['v4_previous_backup']=str(backup)
    try:
        atomic(TARGET,updated,state['mode'])
        atomic(STATE,json.dumps(state).encode(),0o600)
    except Exception:
        atomic(TARGET,current,state['mode']);atomic(STATE,oldstate,0o600)
        raise
    print('V4 installiert: Pufferstatus direkt in Qualität & Stats.')
    print('Testvormerkung wird bis zum Filmstart gespeichert. Bitte Test erneut vormerken und Grün drücken.')

if __name__=='__main__':
    try:main()
    except Exception as error:
        print(str(error));sys.exit(1)
